71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    private final ClinicService clinicService;
77	
78	    private final OwnerMapper ownerMapper;
79	
80	    private final PetMapper petMapper;
81	
82	    private final VisitMapper visitMapper;
83	
84	    private final HouseholdDuplicateValidator householdDuplicateValidator;
85	
86	    private final PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector;
87	
88	    private final NamesakeCounter namesakeCounter;
89	
90	    private final HouseholdSizeCounter householdSizeCounter;
91	
92	    private final CityOwnerCapacityValidator cityOwnerCapacityValidator;
93	
94	    private final DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator;
95	
96	    private final OwnerAuditLogger ownerAuditLogger;
97	
98	    public OwnerRestControllerV1(ClinicService clinicService,
99	                                 OwnerMapper ownerMapper,
100	                                 PetMapper petMapper,
101	                                 VisitMapper visitMapper,
102	                                 HouseholdDuplicateValidator householdDuplicateValidator,
103	                                 PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector,
104	                                 NamesakeCounter namesakeCounter,
105	                                 HouseholdSizeCounter householdSizeCounter,
106	                                 CityOwnerCapacityValidator cityOwnerCapacityValidator,
107	                                 DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator,
108	                                 OwnerAuditLogger ownerAuditLogger) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	        this.householdDuplicateValidator = householdDuplicateValidator;
114	        this.possibleDuplicateOwnerDetector = possibleDuplicateOwnerDetector;
115	        this.namesakeCounter = namesakeCounter;
116	        this.householdSizeCounter = householdSizeCounter;
117	        this.cityOwnerCapacityValidator = cityOwnerCapacityValidator;
118	        this.dailyRegistrationCapacityValidator = dailyRegistrationCapacityValidator;
119	        this.ownerAuditLogger = ownerAuditLogger;
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
125	        Collection<Owner> owners;
126	        if (lastName != null) {
127	            owners = this.clinicService.findOwnerByLastName(lastName);
128	        } else {
129	            owners = this.clinicService.findAllOwners();
130	        }
131	        if (owners.isEmpty()) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
140	        Owner owner = this.clinicService.findOwnerById(ownerId);
141	        if (owner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
150	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
151	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
152	        HttpHeaders headers = new HttpHeaders();
153	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
154	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
155	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
156	        DisposableEmailDomainValidator.validate(owner.getEmail());
157	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
158	        RegistrationDateValidator.validateNotFuture(owner.getRegistrationDate());
159	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
160	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
161	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
162	        owner.setHouseholdId(HouseholdKey.idFor(owner.getLastName(), owner.getPostcode()));
163	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
164	            // An owner sharing a household (same last name and postcode) is otherwise a household
165	            // duplicate. A declared member bypasses this block, and is not a suspected duplicate.
166	            this.householdDuplicateValidator.rejectIfHouseholdExists(owner);
167	            this.possibleDuplicateOwnerDetector.findPossibleDuplicateOf(owner)
168	                .ifPresent(owner::setPossibleDuplicateOf);
169	        }
170	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
171	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
172	        owner.setHouseholdSize(this.householdSizeCounter.count(owner.getHouseholdId()));
173	        String region = RegionResolver.regionFor(owner.getPostcode(), owner.getCity());
174	        owner.setCustomerCode(CustomerCodeGenerator.generate(region, owner.getTelephone(), owner.getLastName()));
175	        this.clinicService.saveOwner(owner);
176	        owner.setMembershipNumber(MembershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
177	        this.ownerAuditLogger.logCreated(owner);
178	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
179	        headers.setLocation(UriComponentsBuilder.newInstance()
180	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
181	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
187	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
188	        if (currentOwner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        currentOwner.setAddress(ownerFieldsDto.getAddress());
192	        currentOwner.setCity(ownerFieldsDto.getCity());
193	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
194	        currentOwner.setLastName(ownerFieldsDto.getLastName());
195	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
196	        this.clinicService.saveOwner(currentOwner);
197	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Transactional
202	    @Override
203	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
204	        Owner owner = this.clinicService.findOwnerById(ownerId);
205	        if (owner == null) {
206	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	        }
208	        this.clinicService.deleteOwner(owner);
209	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
215	        Owner owner = this.clinicService.findOwnerById(ownerId);
216	        if (owner == null) {
217	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	        }
219	        HttpHeaders headers = new HttpHeaders();
220	        Pet pet = petMapper.toPet(petFieldsDto);
221	        owner.setId(ownerId);
222	        pet.setOwner(owner);
223	        pet.getType().setName(null);
224	        this.clinicService.savePet(pet);
225	        PetDto petDto = petMapper.toPetDto(pet);
226	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
227	            .buildAndExpand(pet.getId()).toUri());
228	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
229	    }
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
234	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
235	        if (currentOwner != null) {
236	            Pet currentPet = this.clinicService.findPetById(petId);
237	            if (currentPet != null) {
238	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
239	                currentPet.setName(petFieldsDto.getName());
240	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
241	                this.clinicService.savePet(currentPet);
242	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
243	            }
244	        }
245	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
246	    }
247	
248	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
249	    @Override
250	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
251	        HttpHeaders headers = new HttpHeaders();
252	        Visit visit = visitMapper.toVisit(visitFieldsDto);
253	        Pet pet = new Pet();
254	        pet.setId(petId);
255	        visit.setPet(pet);
256	        this.clinicService.saveVisit(visit);
257	        VisitDto visitDto = visitMapper.toVisitDto(visit);
258	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
259	            .buildAndExpand(visit.getId()).toUri());
260	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
261	    }
262	
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
267	        Owner owner = this.clinicService.findOwnerById(ownerId);
268	        if (owner != null) {
269	            Pet pet = owner.getPet(petId);
270	            if (pet != null) {
271	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
272	            }
273	        }
274	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
275	    }
276	}
