16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.rest.validation.CustomerCodeGenerator;
20	import org.springframework.samples.petclinic.rest.validation.LuhnCheckDigit;
