35	
36	    /**
37	     * Rejects an owner whose required fields are missing or blank.
38	     *
39	     * @param ownerFields the submitted owner fields
40	     * @throws MissingOwnerFieldsException if any of {@code firstName}, {@code lastName},
41	     *                                     {@code address}, {@code city} or {@code telephone}
