17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Set;
20	
21	/**
22	 * Rejects an owner whose email domain is on the disposable-domain blocklist. Disposable
23	 * addresses are throw-away mailboxes that cannot be relied on for contacting an owner, so
24	 * a present email must not use one of these domains.
25	 *
26	 * <p>This is a policy check distinct from {@link EmailNormalizer}'s syntactic validation: it
27	 * operates on an already-normalized (lower-cased, syntactically valid) address.
28	 */
29	public final class DisposableEmailDomainValidator {
30	
31	    private static final Set<String> BLOCKED_DOMAINS =
32	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
33	
34	    private DisposableEmailDomainValidator() {
35	    }
36	
37	    /**
38	     * Rejects a normalized email whose domain is on the disposable-domain blocklist. Email is
39	     * optional, so a {@code null} value is accepted unchanged.
40	     *
41	     * @param email the normalized (lower-cased, syntactically valid) email, or {@code null} if none
42	     * @throws DisposableEmailDomainException if the email's domain is on the blocklist
43	     */
44	    public static void validate(String email) {
45	        if (email == null) {
46	            return;
47	        }
48	        String domain = email.substring(email.indexOf('@') + 1);
49	        if (BLOCKED_DOMAINS.contains(domain)) {
50	            throw new DisposableEmailDomainException(
51	                "Email domain '" + domain + "' is a disposable-domain and is not allowed");
52	        }
53	    }
54	}
