17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import org.springframework.samples.petclinic.model.CityRegions;
20	import org.springframework.samples.petclinic.model.RegionPostcodes;
21	
22	/**
23	 * Validates an owner's optional postcode against its city. The 4-digit format is enforced by the
24	 * schema; this checks the semantic rule that a present postcode must fall within the inclusive
25	 * range fixed for the city's region. A city with no known region accepts any 4-digit postcode.
26	 */
27	public final class PostcodeValidator {
28	
29	    private PostcodeValidator() {
30	    }
31	
32	    /**
33	     * Rejects a postcode that is out of range for its city's region. Postcode is optional, so a
34	     * {@code null} value is accepted.
35	     *
36	     * @param city     the owner's city, used to derive the region
37	     * @param postcode the submitted 4-digit postcode, or {@code null} if none was provided
38	     * @throws InvalidPostcodeException if a value is present but out of range for the city's region
39	     */
40	    public static void validate(String city, String postcode) {
41	        if (postcode == null) {
42	            return;
43	        }
44	        String region = CityRegions.regionOf(city);
45	        if (!RegionPostcodes.isValidForRegion(region, Integer.parseInt(postcode))) {
46	            throw new InvalidPostcodeException(
47	                "Postcode '" + postcode + "' is out of range for region '" + region + "'");
48	        }
49	    }
50	}
