18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.time.temporal.TemporalAdjusters;
22	
23	/**
24	 * Rolls a date forward onto a business day: a Saturday or Sunday becomes the
25	 * following Monday, while a weekday is returned unchanged.
26	 */
27	public final class BusinessDayAdjuster {
28	
29	    private BusinessDayAdjuster() {
30	    }
31	
32	    /**
33	     * Adjusts the given date to a business day.
34	     *
35	     * @param date the date to adjust
36	     * @return the same date when it is a weekday, otherwise the next Monday
37	     */
38	    public static LocalDate toBusinessDay(LocalDate date) {
39	        DayOfWeek day = date.getDayOfWeek();
40	        if (day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY) {
41	            return date.with(TemporalAdjusters.next(DayOfWeek.MONDAY));
42	        }
43	        return date;
44	    }
45	}
