17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.samples.petclinic.service.ClinicService;
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Rejects an owner that would silently join an existing household. Because a household is keyed on
25	 * (last name, postcode) through its {@link HouseholdKey#idFor(String, String) household id}, two
26	 * owners sharing that id belong to the same household; the second one is a household duplicate. The
27	 * caller bypasses this block only when the new owner explicitly opts in via {@code sharesHousehold},
28	 * declaring itself a member rather than a duplicate.
29	 */
30	@Component
31	public class HouseholdDuplicateValidator {
32	
33	    private final ClinicService clinicService;
34	
35	    public HouseholdDuplicateValidator(ClinicService clinicService) {
36	        this.clinicService = clinicService;
37	    }
38	
39	    /**
40	     * Rejects an owner whose household id already belongs to an existing owner. The owner's
41	     * household id must already be assigned when this runs.
42	     *
43	     * @param owner the owner being created
44	     * @throws DuplicateHouseholdException if another owner already belongs to this household
45	     */
46	    public void rejectIfHouseholdExists(Owner owner) {
47	        String householdId = owner.getHouseholdId();
48	        if (householdId == null) {
49	            return;
50	        }
51	        boolean duplicate = this.clinicService.findAllOwners().stream()
52	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
53	        if (duplicate) {
54	            throw new DuplicateHouseholdException(householdId);
55	        }
56	    }
57	}
