17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import org.springframework.stereotype.Component;
20	
21	/**
22	 * Enforces that a city cannot grow beyond {@value #MAX_OWNERS_PER_CITY} owners. The existing owners
23	 * in the city are counted case-insensitively via {@link CityOwnerCounter}; once that count reaches
24	 * the cap, no further owner may be created there.
25	 */
26	@Component
27	public class CityOwnerCapacityValidator {
28	
29	    /** The maximum number of owners allowed in a single city. */
30	    public static final long MAX_OWNERS_PER_CITY = 50;
31	
32	    private final CityOwnerCounter cityOwnerCounter;
33	
34	    public CityOwnerCapacityValidator(CityOwnerCounter cityOwnerCounter) {
35	        this.cityOwnerCounter = cityOwnerCounter;
36	    }
37	
38	    /**
39	     * Rejects an owner whose city already holds {@value #MAX_OWNERS_PER_CITY} or more owners.
40	     *
41	     * @param city the city of the owner being created
42	     * @throws CityOwnerCapacityExceededException if the city is already at capacity
43	     */
44	    public void validateHasCapacity(String city) {
45	        if (this.cityOwnerCounter.count(city) >= MAX_OWNERS_PER_CITY) {
46	            throw new CityOwnerCapacityExceededException(city, MAX_OWNERS_PER_CITY);
47	        }
48	    }
49	}
