58	@ControllerAdvice
59	public class ExceptionControllerAdvice {
60	
61	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
62	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
63	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
64	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
